/// <summary>
///     The <c>AVAPriceIncreaseExecution</c> class is the execution class for <c>AVAPriceIncrease</c>
/// </summary>
class AVAPriceIncreaseExecution
{
    Args                            args;
    AVAPriceIncreaseSet             argsAVAPriceIncreaseSet;
    PriceGroupId                    argsPriceGroupId;
    PriceDiscModule                 argsPriceDiscModule;
    PriceGroupType                  argsPriceGroupType;
    AVAPriceIncreasePriceDiscGroup  argsAVAPriceIncreasePriceDiscGroup;

    AVAPriceIncreaseContract        contract;
    AVAPriceIncreaseSet             contractAVAPriceIncreaseSet;
    PriceGroupId                    contractPriceGroupId;
    PriceDiscModule                 contractPriceDiscModule;
    PriceGroupType                  contractPriceGroupType;
    List                            contractRecIdList;
    ListEnumerator                  contractRecIdListEnumerator;
    int                             contractRecIdListCounter;
    AVAPriceIncreasePriceDiscGroup  contractAVAPriceIncreasePriceDiscGroup;

    boolean                         lJobMode;


}

Method.Source:
/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAPriceIncreaseController      locController;
    AVAPriceIncreaseContract        locContract;

    Common                          locCommon;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    locController   = AVAPriceIncreaseController::newFromArgs(_args);
    locController.parmLoadFromSysLastValue(NoYes::No);

    locContract     = locController.getDataContractObject();
    locContract.parmArgs(_args);

    if(     _args
        &&  _args.record()
        &&  _args.record().RecId
        &&  _args.record().TableId == tableNum(AVAPriceIncreasePriceDiscGroup) )
    {
        locCommon = _args.record();

        if(_args.record().TableId == tableNum(AVAPriceIncreasePriceDiscGroup))
        {
            locAVAPriceIncreasePriceDiscGroup = locCommon;
        }
    }

    locController.startOperation();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = args)
{
    args = _parmValue;

    return args;
}

/// <summary>
///    AVA <c>parmDataContract</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>AVAPriceIncrease</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncrease</c> as return value
/// </returns>
public AVAPriceIncreaseContract parmDataContract(AVAPriceIncreaseContract _parmValue = contract)
{
    contract = _parmValue;

    return contract;
}

/// <summary>
///    AVA <c>parmlJobMode</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean parmlJobMode(boolean _parmValue = lJobMode)
{
    lJobMode = _parmValue;

    return lJobMode;
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncreaseExecution</c> as return value
/// </returns>
public static AVAPriceIncreaseExecution newFromArgs(Args _args)
{
    AVAPriceIncreaseExecution locAVAPriceIncreaseExecution;

    locAVAPriceIncreaseExecution = new AVAPriceIncreaseExecution();
    locAVAPriceIncreaseExecution.parmArgs(_args);
    locAVAPriceIncreaseExecution.init();

    return locAVAPriceIncreaseExecution;
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Common  locCommon;
    boolean locResult;
    boolean locDoResearch;

    if (args && args.record())
    {
        locCommon = args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(AVAPriceIncreasePriceDiscGroup))
        {
            argsAVAPriceIncreasePriceDiscGroup  = locCommon;
            argsAVAPriceIncreaseSet             = argsAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet;
            argsPriceGroupId                    = argsAVAPriceIncreasePriceDiscGroup.GroupId;
            argsPriceDiscModule                 = argsAVAPriceIncreasePriceDiscGroup.Module;
            argsPriceGroupType                  = argsAVAPriceIncreasePriceDiscGroup.Type;
        }
        else
        {
            argsAVAPriceIncreasePriceDiscGroup  = null;
            argsAVAPriceIncreaseSet             = '';
            argsPriceGroupId                    = '';
            argsPriceDiscModule                 = ModuleInventCustVend::Cust;
            argsPriceGroupType                  = PriceGroupType::PriceGroup;
        }
    }

    if(contract)
    {
        contractRecIdList           = new List(Types::Int64);
        contractRecIdList           = contract.parmRecIdList();
        if(contractRecIdList)
        {
            contractRecIdListEnumerator = contractRecIdList.getEnumerator();
            contractRecIdListCounter    = contractRecIdList.elements();
            contractRecIdListEnumerator.reset();
        }
        ttsbegin;
        if(contractRecIdListCounter)
        {
            while(contractRecIdListEnumerator.moveNext())
            {
                contractAVAPriceIncreasePriceDiscGroup  = AVAPriceIncreasePriceDiscGroup::findByRecId(contractRecIdListEnumerator.current());
                locResult                               = contractAVAPriceIncreasePriceDiscGroup.createPriceDiscAdmTableFromAVAPriceIncreaseTable(  AVAPriceIncreaseTable::find(contractAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet), 
                                                                                                                                                    contractAVAPriceIncreasePriceDiscGroup                                                  );
            }
        }
        else
        {
            contractAVAPriceIncreaseSet = contract.parmAVAPriceIncreaseSet();
            contractPriceGroupId        = contract.parmPriceGroupId();
            contractPriceDiscModule     = contract.parmPriceDiscModule();
            contractPriceGroupType      = contract.parmPriceGroupType();
            if(contractAVAPriceIncreaseSet && contractPriceGroupId)
            {
                contractAVAPriceIncreasePriceDiscGroup  = AVAPriceIncreasePriceDiscGroup::find( contractAVAPriceIncreaseSet,
                                                                                                contractPriceGroupId,
                                                                                                contractPriceDiscModule,
                                                                                                contractPriceGroupType      );
                locResult                               = contractAVAPriceIncreasePriceDiscGroup.createPriceDiscAdmTableFromAVAPriceIncreaseTable(  AVAPriceIncreaseTable::find(contractAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet),
                                                                                                                                                    contractAVAPriceIncreasePriceDiscGroup                                                  );
            }
        }
        ttscommit;

        if(locResult)
        {
            locDoResearch = true;
        }
    }
}

