    */
    AVAPriceIncreaseTable           locTableBuffer;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    if(contractAVAPriceIncreasePriceDiscGroup.RecId)
    {

        locTableBuffer = AVAPriceIncreaseTable::find(contractAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet);

        ttsbegin;
        if(locTableBuffer.RecId != 0)
        {
            locAVAPriceIncreasePriceDiscGroup.addFromAVAPriceIncreaseTable(locTableBuffer);
            locAVAPriceIncreasePriceDiscGroup.countPriceGroupMembersFromAVAPriceIncreaseTable(locTableBuffer);
        }
        ttscommit;

    }
}
